module.exports={"html":"<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"description\" content=\"Tool hỗ trợ tự động tra cứu thông tin sản phẩm và thuê bao trên hệ thống SMCS VNPT\">\n  <title>SMCS VNPT - Công Cụ Tra Cứu Số Thuê Bao Tự Động</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <div class=\"app-container\">\n    <!-- Header -->\n    <header class=\"app-header\">\n      <div class=\"header-brand\">\n        <div class=\"logo-badge\">VNPT</div>\n        <div class=\"header-title-group\">\n          <h1>SMCS Tra Cứu Thuê Bao</h1>\n          <p class=\"subtitle\">Hệ Thống Bán Hàng Tập Trung - Giám Sát & Thông Báo Tự Động</p>\n        </div>\n      </div>\n      <div class=\"header-actions\">\n        <span class=\"instance-pill\" id=\"instanceBadge\">💻 Cửa Sổ 1</span>\n        <div class=\"connection-status\" id=\"connectionBadge\">\n          <span class=\"status-indicator ready\"></span>\n          <span id=\"connectionText\">🟢 Trực Tiếp SMCS VNPT</span>\n        </div>\n      </div>\n    </header>\n\n    <!-- Main Grid Layout -->\n    <main class=\"main-layout\">\n      <!-- Cột Trái: Cấu hình & Dữ liệu đầu vào -->\n      <section class=\"left-panel\">\n        <!-- Card 1: Cấu hình Cookie & Hệ Thống -->\n        <div class=\"glass-card config-card\">\n          <div class=\"card-header\">\n            <h2>⚙️ Cấu Hình Kết Nối</h2>\n            <span class=\"auto-save-tag\" id=\"autoSaveIndicator\">Tự động lưu</span>\n          </div>\n          <div class=\"card-body\">\n            <div class=\"form-group\">\n              <label for=\"inputCookie\">\n                Cookie Đăng Nhập (SMCS)\n                <span class=\"tooltip\" title=\"Lấy cookie từ F12 Network trên trang smcs.vnpt.com.vn\">ℹ️</span>\n              </label>\n              <textarea id=\"inputCookie\" rows=\"2\" placeholder=\"Dán chuỗi Cookie từ smcs.vnpt.com.vn vào đây (SESSIONID=...; JSESSIONID=...)\"></textarea>\n            </div>\n\n            <div class=\"form-row\">\n              <div class=\"form-group flex-1\">\n                <label for=\"inputDelay\">\n                  Độ trễ tra cứu (Delay)\n                  <span class=\"tooltip\" title=\"Thời gian nghỉ giữa 2 lần tra cứu, tối thiểu 50ms\">ℹ️</span>\n                </label>\n                <div class=\"input-unit-wrapper\">\n                  <input type=\"number\" id=\"inputDelay\" min=\"50\" step=\"50\" value=\"500\">\n                  <span class=\"unit-text\">mili-giây (ms)</span>\n                </div>\n              </div>\n            </div>\n\n            <!-- Tùy chọn Checkbox -->\n            <div class=\"checkbox-group\">\n              <label class=\"custom-checkbox\">\n                <input type=\"checkbox\" id=\"checkLoop\" checked>\n                <span class=\"checkmark\"></span>\n                <span class=\"checkbox-label\">\n                  <strong>Tra cứu xoay vòng (Loop)</strong>\n                  <small>Lặp lại danh sách cho đến khi dừng hoặc các số trúng ĐK 2</small>\n                </span>\n              </label>\n\n              <label class=\"custom-checkbox\">\n                <input type=\"checkbox\" id=\"checkTelegram\">\n                <span class=\"checkmark\"></span>\n                <span class=\"checkbox-label\">\n                  <strong>Bật thông báo về Telegram</strong>\n                  <small>Gửi tin nhắn khi số thỏa mãn ĐK 1 hoặc ĐK 2</small>\n                </span>\n              </label>\n            </div>\n\n            <!-- Cấu hình Telegram (Mở rộng) -->\n            <div class=\"telegram-subcard\" id=\"telegramConfigBox\">\n              <div class=\"form-group\">\n                <label for=\"inputTeleToken\">Telegram Bot Token</label>\n                <input type=\"password\" id=\"inputTeleToken\" placeholder=\"VD: 7123456789:AAFx...\">\n              </div>\n              <div class=\"form-group\">\n                <label for=\"inputTeleChatId\">Telegram Chat / Group ID</label>\n                <input type=\"text\" id=\"inputTeleChatId\" placeholder=\"VD: -100123456789 hoặc @tennhom\">\n              </div>\n              <div style=\"display: flex; gap: 8px; align-items: center; justify-content: space-between; margin-top: 10px; flex-wrap: wrap;\">\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btnTestTele\">\n                  🔔 Gửi thử Telegram\n                </button>\n                <button type=\"button\" class=\"btn btn-secondary btn-sm text-danger\" id=\"btnResetTeleHistory\" title=\"Xóa danh sách các số đã gửi để bot có thể gửi lại từ đầu\">\n                  🔄 Xóa lịch sử đã gửi\n                </button>\n              </div>\n              <div id=\"teleHistoryStatus\" style=\"font-size: 11px; color: var(--text-muted); margin-top: 6px;\"></div>\n            </div>\n\n            <!-- Nút Lưu Cấu Hình Hệ Thống -->\n            <button type=\"button\" class=\"btn btn-primary\" id=\"btnSaveConfig\" style=\"width: 100%; margin-top: 14px;\">\n              💾 Lưu Cấu Hình Hệ Thống\n            </button>\n          </div>\n        </div>\n\n        <!-- Card 2: Danh Sách Số Thuê Bao Đầu Vào -->\n        <div class=\"glass-card input-card\">\n          <div class=\"card-header\">\n            <h2>📋 Danh Sách Số Thuê Bao</h2>\n            <div class=\"badge-count\" id=\"badgePhoneCount\">0 số</div>\n          </div>\n          <div class=\"card-body\">\n            <div class=\"input-actions-bar\">\n              <button type=\"button\" class=\"btn-text\" id=\"btnLoadSample\">✨ Nạp dữ liệu mẫu</button>\n              <button type=\"button\" class=\"btn-text text-danger\" id=\"btnClearPhones\">Xóa hết</button>\n            </div>\n            <textarea id=\"inputPhoneList\" rows=\"6\" placeholder=\"Nhập hoặc dán danh sách số thuê bao vào đây (Mỗi số 1 dòng hoặc cách nhau bằng dấu phẩy).&#10;Ví dụ:&#10;84942251121&#10;0888441819&#10;84912345671\"></textarea>\n            <div class=\"input-hint\">\n              Hệ thống tự động chuẩn hóa số về đầu <code>84...</code> và loại bỏ trùng lặp.\n            </div>\n\n            <!-- Các nút bấm điều khiển phiên tra cứu -->\n            <div class=\"control-buttons-panel\">\n              <button type=\"button\" class=\"btn btn-primary btn-lg\" id=\"btnStart\">\n                ▶ Bắt Đầu Tra Cứu\n              </button>\n              <button type=\"button\" class=\"btn btn-warning\" id=\"btnPause\" disabled>\n                ⏸ Tạm Dừng\n              </button>\n              <button type=\"button\" class=\"btn btn-danger\" id=\"btnStop\" disabled>\n                ⏹ Dừng Hẳn\n              </button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Cột Phải: Kết Quả & Giám Sát Thời Gian Thực -->\n      <section class=\"right-panel\">\n        <!-- Thống Kê Nhanh (Metric Counters) -->\n        <div class=\"metrics-grid\">\n          <div class=\"metric-card\">\n            <div class=\"metric-icon total\">🔢</div>\n            <div class=\"metric-content\">\n              <span class=\"metric-label\">Tổng Số Nạp</span>\n              <span class=\"metric-value\" id=\"valTotal\">0</span>\n            </div>\n          </div>\n          <div class=\"metric-card\">\n            <div class=\"metric-icon processed\">⚡</div>\n            <div class=\"metric-content\">\n              <span class=\"metric-label\">Lượt Đã Tra</span>\n              <span class=\"metric-value\" id=\"valProcessed\">0</span>\n            </div>\n          </div>\n          <div class=\"metric-card cond1\">\n            <div class=\"metric-icon cond1-icon\">🟢</div>\n            <div class=\"metric-content\">\n              <span class=\"metric-label\">ĐK 1 (Sẵn Sàng)</span>\n              <span class=\"metric-value\" id=\"valCond1\">0</span>\n            </div>\n          </div>\n          <div class=\"metric-card cond2\">\n            <div class=\"metric-icon cond2-icon\">🔴</div>\n            <div class=\"metric-content\">\n              <span class=\"metric-label\">ĐK 2 (Đã Book Số)</span>\n              <span class=\"metric-value\" id=\"valCond2\">0</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Ô RIÊNG: SAO CHÉP NHANH SỐ ĐK 1 (Hiển thị hàng dọc, kèm ngày thay đổi, sắp xếp, xóa từng hàng/tất cả) -->\n        <div class=\"glass-card quick-copy-card\">\n          <div class=\"card-header highlight\">\n            <div class=\"title-with-badge\">\n              <h2>🎯 Ô Riêng: Số Đạt ĐK 1 (Kho VNP & Sẵn Sàng Sử Dụng)</h2>\n              <span class=\"badge-pill\" id=\"badgeCond1Count\">0 số</span>\n            </div>\n            <div class=\"cond1-actions-header\">\n              <select id=\"selectSortCond1\" class=\"sort-select-sm\" title=\"Sắp xếp danh sách ĐK 1\">\n                <option value=\"default\">Sắp xếp: Mặc định</option>\n                <option value=\"phone-asc\">Số: Tăng dần ⬆</option>\n                <option value=\"phone-desc\">Số: Giảm dần ⬇</option>\n                <option value=\"date-desc\">Ngày: Mới nhất ⬇</option>\n                <option value=\"date-asc\">Ngày: Cũ nhất ⬆</option>\n              </select>\n              <button type=\"button\" class=\"btn btn-accent btn-sm\" id=\"btnCopyAllCond1\" title=\"Sao chép toàn bộ số trong ô này để dán vào việc khác\">\n                📋 Sao Chép Tất Cả\n              </button>\n              <button type=\"button\" class=\"btn btn-secondary btn-sm text-danger\" id=\"btnClearAllCond1\" title=\"Xóa toàn bộ số khỏi ô riêng này\">\n                🗑️ Xóa Tất Cả\n              </button>\n            </div>\n          </div>\n          <div class=\"card-body cond1-body-custom\">\n            <div class=\"cond1-table-wrapper\">\n              <table class=\"cond1-table\" id=\"cond1Table\">\n                <thead>\n                  <tr>\n                    <th class=\"col-stt\">STT</th>\n                    <th class=\"col-phone sortable-th\" id=\"thCond1Phone\" data-col=\"phone\">\n                      Số Thuê Bao <span class=\"sort-icon\">⇅</span>\n                    </th>\n                    <th class=\"col-date sortable-th\" id=\"thCond1Date\" data-col=\"date\">\n                      Ngày Thay Đổi <span class=\"sort-icon\">⇅</span>\n                    </th>\n                    <th class=\"col-action\">Thao Tác</th>\n                  </tr>\n                </thead>\n                <tbody id=\"cond1TableBody\">\n                  <tr class=\"empty-row\" id=\"emptyCond1Row\">\n                    <td colspan=\"4\">Chưa có số nào thỏa mãn ĐK 1. Khi tìm thấy số sẵn sàng sử dụng tại Kho chung VNP, số sẽ xuất hiện tại đây theo từng hàng dọc.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n\n        <!-- BẢNG DỮ LIỆU CHÍNH (4 CỘT) -->\n        <div class=\"glass-card data-table-card\">\n          <div class=\"card-header\">\n            <div class=\"table-title-group\">\n              <h2>📊 Kết Quả Tra Cứu Chi Tiết</h2>\n              <span class=\"cycle-indicator\" id=\"cycleBadge\">Vòng: 1</span>\n            </div>\n            <div class=\"table-actions\">\n              <div class=\"search-box\">\n                <input type=\"text\" id=\"inputTableSearch\" placeholder=\"Lọc nhanh kết quả...\">\n              </div>\n              <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btnExportExcel\" title=\"Sao chép toàn bộ bảng với định dạng sẵn sàng dán vào Excel\">\n                📑 Sao Chép Ra Excel\n              </button>\n              <button type=\"button\" class=\"btn-icon\" id=\"btnClearTable\" title=\"Xóa kết quả bảng\">🗑️</button>\n            </div>\n          </div>\n          <div class=\"table-container\">\n            <table class=\"data-table\" id=\"resultsTable\">\n              <thead>\n                <tr>\n                  <th class=\"sortable\" data-col=\"phone\" id=\"thPhone\">\n                    Số Thuê Bao <span class=\"sort-icon\">⇅</span>\n                  </th>\n                  <th class=\"sortable\" data-col=\"status\" id=\"thStatus\">\n                    Trạng Thái Sản Phẩm <span class=\"sort-icon\">⇅</span>\n                  </th>\n                  <th class=\"sortable\" data-col=\"warehouse\" id=\"thWarehouse\">\n                    Hàng Đang Tại Kho <span class=\"sort-icon\">⇅</span>\n                  </th>\n                  <th class=\"sortable\" data-col=\"date\" id=\"thDate\">\n                    Ngày Thay Đổi <span class=\"sort-icon\">⇅</span>\n                  </th>\n                  <th class=\"col-action\">Thao Tác</th>\n                </tr>\n              </thead>\n              <tbody id=\"tableBody\">\n                <tr class=\"empty-row\" id=\"rowTableEmpty\">\n                  <td colspan=\"5\">Chưa có kết quả tra cứu nào. Hãy bấm \"Bắt Đầu Tra Cứu\" để chạy.</td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- Nhật ký sự kiện (Activity Log) -->\n        <div class=\"glass-card logs-card\">\n          <div class=\"card-header\">\n            <h3>📝 Nhật Ký Hoạt Động Trực Tiếp</h3>\n            <button type=\"button\" class=\"btn-text btn-xs\" id=\"btnClearLogs\">Xóa log</button>\n          </div>\n          <div class=\"logs-stream\" id=\"logsContainer\">\n            <div class=\"log-entry info\">\n              <span class=\"log-time\">--:--:--</span>\n              <span class=\"log-text\">Hệ thống đã sẵn sàng khởi chạy.</span>\n            </div>\n          </div>\n        </div>\n      </section>\n    </main>\n\n    <!-- Toast Notification Popup -->\n    <div class=\"toast-container\" id=\"toastContainer\"></div>\n  </div>\n\n  <script src=\"app.js\"></script>\n</body>\n</html>\n","css":":root {\n  --bg-primary: #0a0f1d;\n  --bg-secondary: #111827;\n  --bg-card: rgba(17, 24, 39, 0.85);\n  --bg-card-hover: rgba(31, 41, 55, 0.85);\n  --bg-input: #1e293b;\n  --border-color: rgba(255, 255, 255, 0.08);\n  --border-glow: rgba(0, 150, 255, 0.25);\n  \n  --vnpt-blue: #0066cc;\n  --vnpt-cyan: #00a8ff;\n  --accent-glow: #38bdf8;\n  --success: #10b981;\n  --success-bg: rgba(16, 185, 129, 0.15);\n  --warning: #f59e0b;\n  --warning-bg: rgba(245, 158, 11, 0.15);\n  --danger: #ef4444;\n  --danger-bg: rgba(239, 68, 68, 0.15);\n  \n  --text-main: #f3f4f6;\n  --text-secondary: #9ca3af;\n  --text-muted: #6b7280;\n  \n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 16px;\n  \n  --font-main: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;\n  --font-mono: 'JetBrains Mono', monospace;\n  \n  --shadow-card: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.3);\n  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: var(--font-main);\n  background-color: var(--bg-primary);\n  background-image: \n    radial-gradient(at 0% 0%, rgba(0, 102, 204, 0.15) 0px, transparent 50%),\n    radial-gradient(at 100% 100%, rgba(16, 185, 129, 0.08) 0px, transparent 50%),\n    radial-gradient(at 50% 50%, rgba(30, 41, 59, 0.3) 0px, transparent 70%);\n  background-attachment: fixed;\n  color: var(--text-main);\n  min-height: 100vh;\n  line-height: 1.5;\n  padding: 18px;\n}\n\n/* Container */\n.app-container {\n  max-width: 1600px;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n/* Header */\n.app-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 16px 24px;\n  background: var(--bg-card);\n  backdrop-filter: blur(16px);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-card);\n}\n\n.header-brand {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.logo-badge {\n  background: linear-gradient(135deg, #0052cc, #00a8ff);\n  color: #fff;\n  font-weight: 800;\n  font-size: 1.1rem;\n  letter-spacing: 1px;\n  padding: 10px 16px;\n  border-radius: var(--radius-md);\n  box-shadow: 0 4px 15px rgba(0, 102, 204, 0.4);\n}\n\n.header-title-group h1 {\n  font-size: 1.35rem;\n  font-weight: 700;\n  letter-spacing: -0.5px;\n  background: linear-gradient(90deg, #ffffff, #93c5fd);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.header-title-group .subtitle {\n  font-size: 0.85rem;\n  color: var(--text-secondary);\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 18px;\n}\n\n/* Mode Selector Switch */\n.mode-selector {\n  display: flex;\n  background: var(--bg-input);\n  padding: 4px;\n  border-radius: var(--radius-md);\n  border: 1px solid var(--border-color);\n}\n\n.mode-btn {\n  background: transparent;\n  border: none;\n  color: var(--text-secondary);\n  padding: 6px 14px;\n  border-radius: var(--radius-sm);\n  font-size: 0.82rem;\n  font-weight: 600;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  transition: var(--transition);\n}\n\n.mode-btn.active {\n  background: rgba(255, 255, 255, 0.1);\n  color: #fff;\n}\n\n.dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n}\n.dot.mock { background: #38bdf8; box-shadow: 0 0 8px #38bdf8; }\n.dot.live { background: #10b981; box-shadow: 0 0 8px #10b981; }\n\n.instance-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: rgba(37, 99, 235, 0.15);\n  border: 1px solid rgba(37, 99, 235, 0.4);\n  color: #93c5fd;\n  padding: 6px 14px;\n  border-radius: var(--radius-md);\n  font-size: 0.85rem;\n  font-weight: 600;\n  letter-spacing: 0.3px;\n  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.15);\n}\n\n.connection-status {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 0.85rem;\n  font-weight: 500;\n  color: var(--text-secondary);\n  padding: 6px 12px;\n  background: rgba(255, 255, 255, 0.03);\n  border-radius: var(--radius-md);\n  border: 1px solid var(--border-color);\n}\n\n.status-indicator {\n  width: 10px;\n  height: 10px;\n  border-radius: 50%;\n}\n.status-indicator.ready { background: var(--text-muted); }\n.status-indicator.running { background: var(--success); box-shadow: 0 0 10px var(--success); animation: pulse 1.5s infinite; }\n.status-indicator.paused { background: var(--warning); box-shadow: 0 0 10px var(--warning); }\n\n@keyframes pulse {\n  0%, 100% { opacity: 1; transform: scale(1); }\n  50% { opacity: 0.6; transform: scale(1.15); }\n}\n\n/* Layout */\n.main-layout {\n  display: grid;\n  grid-template-columns: 460px 1fr;\n  gap: 20px;\n}\n\n@media (max-width: 1200px) {\n  .main-layout {\n    grid-template-columns: 1fr;\n  }\n}\n\n/* Glass Card */\n.glass-card {\n  background: var(--bg-card);\n  backdrop-filter: blur(14px);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-card);\n  margin-bottom: 20px;\n  transition: var(--transition);\n  overflow: hidden;\n}\n\n.glass-card:hover {\n  border-color: rgba(255, 255, 255, 0.12);\n}\n\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 16px 20px;\n  border-bottom: 1px solid var(--border-color);\n  background: rgba(255, 255, 255, 0.02);\n}\n\n.card-header h2 {\n  font-size: 1.05rem;\n  font-weight: 600;\n  color: #fff;\n}\n\n.card-header.highlight {\n  background: linear-gradient(90deg, rgba(16, 185, 129, 0.12), transparent);\n  border-bottom: 1px solid rgba(16, 185, 129, 0.3);\n}\n\n.title-with-badge {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.badge-pill {\n  font-size: 0.75rem;\n  font-weight: 700;\n  background: var(--success-bg);\n  color: var(--success);\n  padding: 3px 10px;\n  border-radius: 20px;\n  border: 1px solid rgba(16, 185, 129, 0.3);\n}\n\n.auto-save-tag {\n  font-size: 0.72rem;\n  color: var(--accent-glow);\n  background: rgba(56, 189, 248, 0.1);\n  padding: 2px 8px;\n  border-radius: var(--radius-sm);\n}\n\n.card-body {\n  padding: 18px 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n/* Form controls */\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.form-row {\n  display: flex;\n  gap: 12px;\n}\n\n.flex-1 { flex: 1; }\n\nlabel {\n  font-size: 0.83rem;\n  font-weight: 600;\n  color: var(--text-secondary);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.tooltip {\n  cursor: help;\n  font-size: 0.8rem;\n  opacity: 0.7;\n}\n\ninput[type=\"text\"],\ninput[type=\"password\"],\ninput[type=\"number\"],\ntextarea {\n  width: 100%;\n  background: var(--bg-input);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  color: var(--text-main);\n  font-family: inherit;\n  font-size: 0.88rem;\n  padding: 10px 14px;\n  transition: var(--transition);\n  outline: none;\n}\n\ninput:focus, textarea:focus {\n  border-color: var(--vnpt-cyan);\n  box-shadow: 0 0 0 3px rgba(0, 168, 255, 0.2);\n}\n\ntextarea {\n  resize: vertical;\n  font-family: var(--font-mono);\n  font-size: 0.82rem;\n  line-height: 1.5;\n}\n\n.input-unit-wrapper {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n\n.input-unit-wrapper input {\n  padding-right: 120px;\n}\n\n.unit-text {\n  position: absolute;\n  right: 12px;\n  font-size: 0.8rem;\n  color: var(--text-muted);\n  pointer-events: none;\n}\n\n/* Checkbox */\n.checkbox-group {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  background: rgba(255, 255, 255, 0.02);\n  padding: 12px 14px;\n  border-radius: var(--radius-md);\n  border: 1px solid var(--border-color);\n}\n\n.custom-checkbox {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  cursor: pointer;\n  user-select: none;\n}\n\n.custom-checkbox input {\n  position: absolute;\n  opacity: 0;\n  cursor: pointer;\n}\n\n.checkmark {\n  width: 20px;\n  height: 20px;\n  background: var(--bg-input);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  flex-shrink: 0;\n  position: relative;\n  transition: var(--transition);\n  margin-top: 2px;\n}\n\n.custom-checkbox input:checked ~ .checkmark {\n  background: var(--vnpt-blue);\n  border-color: var(--vnpt-cyan);\n}\n\n.checkmark:after {\n  content: \"\";\n  position: absolute;\n  display: none;\n  left: 6px;\n  top: 2px;\n  width: 5px;\n  height: 10px;\n  border: solid white;\n  border-width: 0 2px 2px 0;\n  transform: rotate(45deg);\n}\n\n.custom-checkbox input:checked ~ .checkmark:after {\n  display: block;\n}\n\n.checkbox-label strong {\n  display: block;\n  font-size: 0.86rem;\n  color: var(--text-main);\n}\n\n.checkbox-label small {\n  display: block;\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  margin-top: 1px;\n}\n\n/* Telegram Subcard */\n.telegram-subcard {\n  display: none;\n  flex-direction: column;\n  gap: 12px;\n  padding: 14px;\n  background: rgba(0, 102, 204, 0.08);\n  border-radius: var(--radius-md);\n  border: 1px solid rgba(0, 102, 204, 0.3);\n  animation: fadeIn 0.3s ease;\n}\n\n.telegram-subcard.visible {\n  display: flex;\n}\n\n@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(-6px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n/* Input phone section */\n.input-actions-bar {\n  display: flex;\n  justify-content: flex-end;\n  gap: 10px;\n}\n\n.btn-text {\n  background: none;\n  border: none;\n  color: var(--vnpt-cyan);\n  font-size: 0.8rem;\n  font-weight: 600;\n  cursor: pointer;\n  padding: 4px 8px;\n  border-radius: var(--radius-sm);\n}\n\n.btn-text:hover {\n  background: rgba(255, 255, 255, 0.05);\n}\n\n.btn-text.text-danger {\n  color: var(--danger);\n}\n\n.input-hint {\n  font-size: 0.76rem;\n  color: var(--text-muted);\n}\n\n.input-hint code {\n  background: rgba(255, 255, 255, 0.08);\n  padding: 2px 6px;\n  border-radius: 4px;\n  color: var(--vnpt-cyan);\n}\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 10px 18px;\n  border-radius: var(--radius-md);\n  font-size: 0.88rem;\n  font-weight: 600;\n  cursor: pointer;\n  border: none;\n  transition: var(--transition);\n}\n\n.btn:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n  filter: grayscale(0.5);\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, #0066cc, #0099ff);\n  color: #fff;\n  box-shadow: 0 4px 15px rgba(0, 102, 204, 0.4);\n}\n\n.btn-primary:hover:not(:disabled) {\n  background: linear-gradient(135deg, #0052a3, #0088e6);\n  transform: translateY(-1px);\n  box-shadow: 0 6px 20px rgba(0, 102, 204, 0.5);\n}\n\n.btn-secondary {\n  background: rgba(255, 255, 255, 0.06);\n  color: var(--text-main);\n  border: 1px solid var(--border-color);\n}\n\n.btn-secondary:hover:not(:disabled) {\n  background: rgba(255, 255, 255, 0.12);\n}\n\n.btn-warning {\n  background: linear-gradient(135deg, #d97706, #f59e0b);\n  color: #fff;\n}\n\n.btn-danger {\n  background: linear-gradient(135deg, #dc2626, #ef4444);\n  color: #fff;\n}\n\n.btn-accent {\n  background: linear-gradient(135deg, #059669, #10b981);\n  color: #fff;\n  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);\n}\n\n.btn-accent:hover:not(:disabled) {\n  transform: translateY(-1px);\n}\n\n.btn-sm {\n  padding: 6px 12px;\n  font-size: 0.8rem;\n}\n\n.btn-xs {\n  padding: 2px 6px;\n  font-size: 0.72rem;\n}\n\n.btn-lg {\n  padding: 13px 22px;\n  font-size: 0.95rem;\n}\n\n.btn-icon {\n  background: transparent;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  padding: 6px 10px;\n  cursor: pointer;\n  color: var(--text-secondary);\n}\n\n.btn-icon:hover {\n  background: rgba(255, 255, 255, 0.08);\n  color: #fff;\n}\n\n.control-buttons-panel {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1fr;\n  gap: 10px;\n  margin-top: 10px;\n}\n\n.control-buttons-panel .btn-primary {\n  grid-column: span 3;\n}\n\n/* Metrics Grid */\n.metrics-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 16px;\n  margin-bottom: 20px;\n}\n\n@media (max-width: 768px) {\n  .metrics-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n.metric-card {\n  background: var(--bg-card);\n  backdrop-filter: blur(14px);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 14px 18px;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  box-shadow: var(--shadow-card);\n}\n\n.metric-icon {\n  width: 44px;\n  height: 44px;\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.3rem;\n  background: rgba(255, 255, 255, 0.05);\n}\n\n.metric-content {\n  display: flex;\n  flex-direction: column;\n}\n\n.metric-label {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  font-weight: 500;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.metric-value {\n  font-size: 1.5rem;\n  font-weight: 800;\n  font-family: var(--font-mono);\n  color: #fff;\n}\n\n.metric-card.cond1 {\n  border-color: rgba(16, 185, 129, 0.3);\n  background: linear-gradient(135deg, rgba(16, 185, 129, 0.08), rgba(17, 24, 39, 0.9));\n}\n.metric-card.cond1 .metric-value { color: var(--success); }\n\n.metric-card.cond2 {\n  border-color: rgba(239, 68, 68, 0.3);\n  background: linear-gradient(135deg, rgba(239, 68, 68, 0.08), rgba(17, 24, 39, 0.9));\n}\n.metric-card.cond2 .metric-value { color: var(--danger); }\n\n/* Quick Copy Box (Condition 1) */\n.quick-copy-card {\n  border: 1px solid rgba(16, 185, 129, 0.35);\n  box-shadow: 0 4px 20px rgba(16, 185, 129, 0.12);\n}\n\n.quick-copy-container {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  min-height: 52px;\n  max-height: 140px;\n  overflow-y: auto;\n  align-items: center;\n}\n\n.phone-tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  background: rgba(16, 185, 129, 0.15);\n  border: 1px solid rgba(16, 185, 129, 0.4);\n  color: #a7f3d0;\n  padding: 6px 12px;\n  border-radius: var(--radius-sm);\n  font-family: var(--font-mono);\n  font-weight: 600;\n  font-size: 0.88rem;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.phone-tag:hover {\n  background: rgba(16, 185, 129, 0.3);\n  transform: translateY(-2px);\n  box-shadow: 0 4px 10px rgba(16, 185, 129, 0.3);\n}\n\n.phone-tag:active {\n  transform: scale(0.96);\n}\n\n.phone-tag .copy-icon {\n  font-size: 0.78rem;\n  opacity: 0.7;\n}\n\n.empty-state {\n  color: var(--text-muted);\n  font-size: 0.82rem;\n  font-style: italic;\n  width: 100%;\n}\n\n/* Data Table */\n.data-table-card {\n  display: flex;\n  flex-direction: column;\n}\n\n.table-title-group {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.cycle-indicator {\n  font-size: 0.75rem;\n  background: rgba(56, 189, 248, 0.15);\n  color: var(--accent-glow);\n  padding: 2px 8px;\n  border-radius: 20px;\n  font-weight: 600;\n}\n\n.table-actions {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.search-box input {\n  padding: 6px 12px;\n  font-size: 0.82rem;\n  width: 180px;\n}\n\n.table-container {\n  overflow-x: auto;\n  max-height: 480px;\n}\n\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n  font-size: 0.86rem;\n}\n\n.data-table th {\n  background: #151d2f;\n  color: var(--text-secondary);\n  font-weight: 600;\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--border-color);\n  position: sticky;\n  top: 0;\n  z-index: 2;\n  user-select: none;\n}\n\n.data-table th.sortable {\n  cursor: pointer;\n}\n\n.data-table th.sortable:hover {\n  color: #fff;\n  background: #1b253b;\n}\n\n.data-table th.sortable.sorted {\n  color: #fff;\n  background: rgba(37, 99, 235, 0.2);\n  border-bottom: 2px solid var(--accent);\n}\n\n.data-table th.sortable.sorted .sort-icon {\n  opacity: 1;\n  color: var(--accent);\n  font-weight: 700;\n}\n\n.sort-icon {\n  font-size: 0.75rem;\n  margin-left: 4px;\n  opacity: 0.6;\n}\n\n.data-table td {\n  padding: 12px 16px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.04);\n  color: var(--text-main);\n}\n\n.data-table tbody tr {\n  transition: var(--transition);\n}\n\n.data-table tbody tr:hover {\n  background: rgba(255, 255, 255, 0.03);\n}\n\n.data-table tr.row-cond1 {\n  background: rgba(16, 185, 129, 0.08);\n}\n.data-table tr.row-cond1:hover {\n  background: rgba(16, 185, 129, 0.14);\n}\n\n.data-table tr.row-cond2 {\n  background: rgba(239, 68, 68, 0.08);\n}\n.data-table tr.row-cond2:hover {\n  background: rgba(239, 68, 68, 0.14);\n}\n\n.cell-phone {\n  font-family: var(--font-mono);\n  font-weight: 600;\n  color: #fff;\n}\n\n.cell-date {\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  color: var(--text-secondary);\n}\n\n/* Status Tags */\n.status-tag {\n  display: inline-block;\n  padding: 3px 8px;\n  border-radius: var(--radius-sm);\n  font-size: 0.78rem;\n  font-weight: 600;\n}\n\n.status-tag.ready {\n  background: var(--success-bg);\n  color: var(--success);\n  border: 1px solid rgba(16, 185, 129, 0.3);\n}\n\n.status-tag.booked {\n  background: var(--danger-bg);\n  color: var(--danger);\n  border: 1px solid rgba(239, 68, 68, 0.3);\n}\n\n.status-tag.neutral {\n  background: rgba(255, 255, 255, 0.06);\n  color: var(--text-secondary);\n}\n\n.warehouse-tag {\n  color: #93c5fd;\n}\n\n.btn-row-copy {\n  background: transparent;\n  border: none;\n  color: var(--vnpt-cyan);\n  cursor: pointer;\n  padding: 4px;\n  border-radius: 4px;\n  font-size: 0.85rem;\n}\n\n.btn-row-copy:hover {\n  background: rgba(255, 255, 255, 0.1);\n}\n\n.empty-row td {\n  text-align: center;\n  padding: 30px;\n  color: var(--text-muted);\n}\n\n/* Activity Logs */\n.logs-stream {\n  max-height: 180px;\n  overflow-y: auto;\n  font-family: var(--font-mono);\n  font-size: 0.78rem;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 12px 16px;\n  background: #090d16;\n  border-radius: var(--radius-md);\n  margin: 12px 18px 18px 18px;\n}\n\n.log-entry {\n  display: flex;\n  gap: 10px;\n  line-height: 1.4;\n}\n\n.log-time {\n  color: var(--text-muted);\n  flex-shrink: 0;\n}\n\n.log-entry.info .log-text { color: #93c5fd; }\n.log-entry.success .log-text { color: #86efac; }\n.log-entry.warn .log-text { color: #fde047; }\n.log-entry.error .log-text { color: #fca5a5; }\n\n/* Toast Notifications */\n.toast-container {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  z-index: 9999;\n}\n\n.toast {\n  padding: 12px 18px;\n  border-radius: var(--radius-md);\n  background: #1f2937;\n  color: #fff;\n  font-size: 0.85rem;\n  font-weight: 500;\n  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n  border: 1px solid var(--border-color);\n  animation: slideUp 0.3s ease;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.toast.success { border-color: var(--success); }\n.toast.error { border-color: var(--danger); }\n\n@keyframes slideUp {\n  from { transform: translateY(20px); opacity: 0; }\n  to { transform: translateY(0); opacity: 1; }\n}\n\n/* Ô Riêng ĐK1 - Dạng bảng hàng dọc mới */\n.cond1-actions-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.sort-select-sm {\n  background: var(--bg-input);\n  color: var(--text-main);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  padding: 5px 8px;\n  font-size: 0.78rem;\n  font-weight: 500;\n  outline: none;\n  cursor: pointer;\n}\n\n.sort-select-sm:focus {\n  border-color: var(--success);\n}\n\n.cond1-body-custom {\n  padding: 0 !important;\n}\n\n.cond1-table-wrapper {\n  max-height: 250px;\n  overflow-y: auto;\n  border-radius: 0 0 var(--radius-lg) var(--radius-lg);\n}\n\n.cond1-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.84rem;\n  text-align: left;\n}\n\n.cond1-table th {\n  background: rgba(16, 185, 129, 0.12);\n  color: #a7f3d0;\n  font-weight: 600;\n  padding: 10px 14px;\n  border-bottom: 1px solid rgba(16, 185, 129, 0.25);\n  position: sticky;\n  top: 0;\n  z-index: 2;\n  user-select: none;\n}\n\n.cond1-table th.sortable-th {\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.cond1-table th.sortable-th:hover {\n  background: rgba(16, 185, 129, 0.2);\n  color: #fff;\n}\n\n.cond1-table th.sortable-th.sorted {\n  background: rgba(16, 185, 129, 0.25);\n  color: #fff;\n  border-bottom: 2px solid var(--success);\n}\n\n.cond1-table td {\n  padding: 9px 14px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.04);\n  color: var(--text-main);\n}\n\n.cond1-table tbody tr {\n  transition: var(--transition);\n}\n\n.cond1-table tbody tr:hover {\n  background: rgba(16, 185, 129, 0.08);\n}\n\n.cond1-table .col-stt {\n  width: 50px;\n  text-align: center;\n  color: var(--text-muted);\n}\n\n.cond1-table .col-phone {\n  font-family: var(--font-mono);\n  font-weight: 600;\n  color: #34d399;\n}\n\n.cond1-table .col-date {\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  color: var(--text-secondary);\n}\n\n.cond1-table .col-action {\n  width: 150px;\n  text-align: right;\n}\n\n.cond1-action-buttons {\n  display: flex;\n  gap: 6px;\n  justify-content: flex-end;\n}\n\n.btn-cell-copy, .btn-cell-delete {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  padding: 4px 8px;\n  font-size: 0.76rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.btn-cell-copy {\n  color: var(--vnpt-cyan);\n}\n\n.btn-cell-copy:hover {\n  background: rgba(0, 168, 255, 0.2);\n  border-color: var(--vnpt-cyan);\n  color: #fff;\n}\n\n.btn-cell-delete {\n  color: var(--danger);\n}\n\n.btn-cell-delete:hover {\n  background: rgba(239, 68, 68, 0.2);\n  border-color: var(--danger);\n  color: #fff;\n}\n","js":"/**\n * Frontend Controller for SMCS Tool\n */\n\n// State\nlet appState = {\n  status: 'idle', // 'idle' | 'running' | 'paused' | 'stopped' | 'completed'\n  mode: 'live',\n  tableData: [], // { phone, productStatus, warehouse, updatedDate, isCondition1, isCondition2, cycle }\n  condition1Items: [], // [{ phone, updatedDate }]\n  sortCond1Col: 'default',\n  sortCond1Asc: true,\n  sortCol: null,\n  sortAsc: true,\n  searchKeyword: ''\n};\n\n// DOM Elements\nconst elements = {\n  // Status & Connection\n  connectionBadge: document.getElementById('connectionBadge'),\n  connectionText: document.getElementById('connectionText'),\n  autoSaveIndicator: document.getElementById('autoSaveIndicator'),\n\n  // Form Controls\n  inputCookie: document.getElementById('inputCookie'),\n  inputDelay: document.getElementById('inputDelay'),\n  checkLoop: document.getElementById('checkLoop'),\n  checkTelegram: document.getElementById('checkTelegram'),\n  telegramConfigBox: document.getElementById('telegramConfigBox'),\n  inputTeleToken: document.getElementById('inputTeleToken'),\n  inputTeleChatId: document.getElementById('inputTeleChatId'),\n  btnTestTele: document.getElementById('btnTestTele'),\n  btnResetTeleHistory: document.getElementById('btnResetTeleHistory'),\n  teleHistoryStatus: document.getElementById('teleHistoryStatus'),\n  btnSaveConfig: document.getElementById('btnSaveConfig'),\n\n  // Phone input & Actions\n  inputPhoneList: document.getElementById('inputPhoneList'),\n  badgePhoneCount: document.getElementById('badgePhoneCount'),\n  btnLoadSample: document.getElementById('btnLoadSample'),\n  btnClearPhones: document.getElementById('btnClearPhones'),\n  btnStart: document.getElementById('btnStart'),\n  btnPause: document.getElementById('btnPause'),\n  btnStop: document.getElementById('btnStop'),\n\n  // Metrics\n  valTotal: document.getElementById('valTotal'),\n  valProcessed: document.getElementById('valProcessed'),\n  valCond1: document.getElementById('valCond1'),\n  valCond2: document.getElementById('valCond2'),\n\n  // Ô Riêng ĐK 1\n  badgeCond1Count: document.getElementById('badgeCond1Count'),\n  selectSortCond1: document.getElementById('selectSortCond1'),\n  btnCopyAllCond1: document.getElementById('btnCopyAllCond1'),\n  btnClearAllCond1: document.getElementById('btnClearAllCond1'),\n  cond1Table: document.getElementById('cond1Table'),\n  cond1TableBody: document.getElementById('cond1TableBody'),\n  emptyCond1Row: document.getElementById('emptyCond1Row'),\n  thCond1Phone: document.getElementById('thCond1Phone'),\n  thCond1Date: document.getElementById('thCond1Date'),\n\n  // Table\n  cycleBadge: document.getElementById('cycleBadge'),\n  inputTableSearch: document.getElementById('inputTableSearch'),\n  btnExportExcel: document.getElementById('btnExportExcel'),\n  btnClearTable: document.getElementById('btnClearTable'),\n  resultsTable: document.getElementById('resultsTable'),\n  tableBody: document.getElementById('tableBody'),\n  rowTableEmpty: document.getElementById('rowTableEmpty'),\n\n  // Logs & Toast\n  logsContainer: document.getElementById('logsContainer'),\n  btnClearLogs: document.getElementById('btnClearLogs'),\n  toastContainer: document.getElementById('toastContainer')\n};\n\n// Mẫu danh sách SĐT (có chứa các số trong tài liệu Word)\nconst SAMPLE_PHONES = [\n  '84942251121', // Số trong doc: Lần 1 ra ĐK1, sau đó ra ĐK2\n  '84888441819', // Số trong doc hình 4: Kho thu hồi\n  '0912345001',  // Sẽ chuẩn hóa thành 84912345001 (ĐK 1)\n  '84912345002', // ĐK 2 (\"Đã book số\")\n  '0912345003',  // Kho số khác\n  '84912345004'  // Trạng thái bình thường\n].join('\\n');\n\n// Khởi chạy\ndocument.addEventListener('DOMContentLoaded', () => {\n  initEventListeners();\n  loadSavedSettings();\n  loadTeleHistoryStats();\n  initEventSource();\n});\n\n/**\n * Tải cài đặt đã lưu từ Backend kết hợp LocalStorage của trình duyệt\n */\nasync function loadSavedSettings() {\n  let serverSettings = null;\n  try {\n    const res = await fetch('/api/settings');\n    const data = await res.json();\n    if (data.success && data.settings) {\n      serverSettings = data.settings;\n    }\n  } catch (err) {\n    console.warn('Không thể tải cài đặt từ server:', err);\n  }\n\n  // Đọc từ LocalStorage trình duyệt phòng khi server chưa có hoặc mới mở lại\n  let localSettings = null;\n  try {\n    const raw = localStorage.getItem('smcs_settings');\n    if (raw) localSettings = JSON.parse(raw);\n  } catch (err) {}\n\n  const merged = { ...(localSettings || {}), ...(serverSettings || {}) };\n  // Nếu server có trường rỗng nhưng localStorage có giá trị thì lấy từ local\n  if (!merged.cookie && localSettings?.cookie) merged.cookie = localSettings.cookie;\n  if (!merged.telegramToken && localSettings?.telegramToken) merged.telegramToken = localSettings.telegramToken;\n  if (!merged.telegramChatId && localSettings?.telegramChatId) merged.telegramChatId = localSettings.telegramChatId;\n\n  applySettingsToUI(merged);\n}\n\nfunction applySettingsToUI(s) {\n  if (s.cookie) elements.inputCookie.value = s.cookie;\n  if (s.delayMs) elements.inputDelay.value = s.delayMs;\n  if (typeof s.enableLoop === 'boolean') elements.checkLoop.checked = s.enableLoop;\n  if (typeof s.enableTelegram === 'boolean') {\n    elements.checkTelegram.checked = s.enableTelegram;\n    toggleTelegramBox(s.enableTelegram);\n  }\n  if (s.telegramToken) elements.inputTeleToken.value = s.telegramToken;\n  if (s.telegramChatId) elements.inputTeleChatId.value = s.telegramChatId;\n}\n\n/**\n * Lưu cài đặt vào cả Server (config.json) và LocalStorage\n */\nlet saveTimeout = null;\nfunction triggerAutoSave() {\n  if (saveTimeout) clearTimeout(saveTimeout);\n  saveTimeout = setTimeout(() => {\n    saveSettings(false);\n  }, 600);\n}\n\nasync function saveSettings(manual = false) {\n  const payload = getFormSettings();\n\n  // 1. Lưu vào LocalStorage trình duyệt ngay lập tức\n  try {\n    localStorage.setItem('smcs_settings', JSON.stringify(payload));\n  } catch (e) {}\n\n  elements.autoSaveIndicator.textContent = 'Đang lưu...';\n  elements.autoSaveIndicator.style.color = 'var(--warning)';\n\n  // 2. Lưu vào backend config.json\n  try {\n    const res = await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(payload)\n    });\n    const data = await res.json();\n    elements.autoSaveIndicator.textContent = 'Đã lưu';\n    elements.autoSaveIndicator.style.color = 'var(--success)';\n\n    if (manual) {\n      showToast('💾 Đã lưu cấu hình hệ thống thành công (vào máy & trình duyệt)!', 'success');\n      appendLog('success', 'Đã lưu cấu hình vào config.json và bộ nhớ trình duyệt.');\n    }\n\n    setTimeout(() => {\n      elements.autoSaveIndicator.textContent = 'Tự động lưu';\n      elements.autoSaveIndicator.style.color = 'var(--accent-glow)';\n    }, 2000);\n  } catch (err) {\n    elements.autoSaveIndicator.textContent = 'Lỗi lưu';\n    elements.autoSaveIndicator.style.color = 'var(--danger)';\n    if (manual) {\n      showToast(`Lỗi lưu cấu hình: ${err.message}`, 'error');\n    }\n  }\n}\n\nfunction getFormSettings() {\n  return {\n    mode: appState.mode,\n    cookie: elements.inputCookie.value.trim(),\n    delayMs: Math.max(50, Number(elements.inputDelay.value) || 500),\n    enableLoop: elements.checkLoop.checked,\n    enableTelegram: elements.checkTelegram.checked,\n    telegramToken: elements.inputTeleToken.value.trim(),\n    telegramChatId: elements.inputTeleChatId.value.trim()\n  };\n}\n\n/**\n * Kết nối Server-Sent Events (SSE) để cập nhật dữ liệu thời gian thực\n */\nfunction initEventSource() {\n  const evtSource = new EventSource('/api/stream');\n\n  evtSource.addEventListener('initial_state', (e) => {\n    const state = JSON.parse(e.data);\n    if (state.instanceInfo) {\n      const idx = state.instanceInfo.instanceIndex || 1;\n      const port = state.instanceInfo.port || 3000;\n      document.title = `SMCS Tra Cứu - Cửa Sổ ${idx}`;\n      const badge = document.getElementById('instanceBadge');\n      if (badge) {\n        badge.textContent = `💻 Cửa Sổ ${idx} (Port: ${port})`;\n        if (idx > 1) {\n          badge.style.background = 'rgba(16, 185, 129, 0.18)';\n          badge.style.borderColor = 'rgba(16, 185, 129, 0.45)';\n          badge.style.color = '#a7f3d0';\n        }\n      }\n    }\n    updateRuntimeStatus(state.status);\n    if (state.stats) updateStats(state.stats);\n    if (state.condition1Items && state.condition1Items.length > 0) {\n      appState.condition1Items = [...state.condition1Items];\n      renderCondition1Table();\n    } else if (state.condition1Numbers && state.condition1Numbers.length > 0) {\n      appState.condition1Items = state.condition1Numbers.map(p => ({\n        phone: p,\n        updatedDate: new Date().toLocaleString('vi-VN')\n      }));\n      renderCondition1Table();\n    }\n  });\n\n  evtSource.addEventListener('status_change', (e) => {\n    const state = JSON.parse(e.data);\n    updateRuntimeStatus(state.status);\n    if (state.stats) updateStats(state.stats);\n  });\n\n  evtSource.addEventListener('item_processed', (e) => {\n    const item = JSON.parse(e.data);\n    addTableRow(item);\n    loadTeleHistoryStats();\n  });\n\n  evtSource.addEventListener('condition1_found', (e) => {\n    const data = JSON.parse(e.data);\n    addCondition1Item(data.phone, data.updatedDate);\n    showToast(`🟢 Tìm thấy số ĐK 1: ${data.phone}`, 'success');\n  });\n\n  evtSource.addEventListener('stats_update', (e) => {\n    const stats = JSON.parse(e.data);\n    updateStats(stats);\n  });\n\n  evtSource.addEventListener('log', (e) => {\n    const log = JSON.parse(e.data);\n    appendLog(log.type, log.message);\n  });\n\n  evtSource.onerror = () => {\n    elements.connectionText.textContent = 'Mất kết nối máy chủ';\n    elements.connectionBadge.querySelector('.status-indicator').className = 'status-indicator paused';\n  };\n}\n\n/**\n * Lắng nghe các sự kiện tương tác\n */\nfunction initEventListeners() {\n  // Tự động lưu khi thay đổi form\n  [elements.inputCookie, elements.inputDelay, elements.inputTeleToken, elements.inputTeleChatId].forEach(el => {\n    el.addEventListener('input', triggerAutoSave);\n  });\n\n  elements.checkLoop.addEventListener('change', triggerAutoSave);\n  elements.checkTelegram.addEventListener('change', (e) => {\n    toggleTelegramBox(e.target.checked);\n    triggerAutoSave();\n  });\n\n  // Số lượng số nhập vào\n  elements.inputPhoneList.addEventListener('input', updatePhoneInputCount);\n\n  // Nạp mẫu & Xóa\n  elements.btnLoadSample.addEventListener('click', () => {\n    elements.inputPhoneList.value = SAMPLE_PHONES;\n    updatePhoneInputCount();\n    showToast('Đã nạp 6 số mẫu thử nghiệm!', 'success');\n  });\n\n  elements.btnClearPhones.addEventListener('click', () => {\n    elements.inputPhoneList.value = '';\n    updatePhoneInputCount();\n  });\n\n  // Nút Lưu Cấu Hình Hệ Thống\n  if (elements.btnSaveConfig) {\n    elements.btnSaveConfig.addEventListener('click', () => saveSettings(true));\n  }\n\n  // Điều khiển\n  elements.btnStart.addEventListener('click', handleStart);\n  elements.btnPause.addEventListener('click', handlePause);\n  elements.btnStop.addEventListener('click', handleStop);\n\n  // Test Telegram & Quản lý lịch sử Telegram\n  elements.btnTestTele.addEventListener('click', handleTestTelegram);\n  if (elements.btnResetTeleHistory) {\n    elements.btnResetTeleHistory.addEventListener('click', handleResetTeleHistory);\n  }\n\n  // Ô Riêng ĐK 1: Sắp xếp, Copy tất cả, Xóa tất cả\n  if (elements.selectSortCond1) {\n    elements.selectSortCond1.addEventListener('change', (e) => {\n      setCond1Sort(e.target.value);\n    });\n  }\n\n  if (elements.thCond1Phone) {\n    elements.thCond1Phone.addEventListener('click', () => {\n      toggleCond1HeaderSort('phone');\n    });\n  }\n\n  if (elements.thCond1Date) {\n    elements.thCond1Date.addEventListener('click', () => {\n      toggleCond1HeaderSort('date');\n    });\n  }\n\n  if (elements.btnCopyAllCond1) {\n    elements.btnCopyAllCond1.addEventListener('click', handleCopyAllCond1);\n  }\n\n  if (elements.btnClearAllCond1) {\n    elements.btnClearAllCond1.addEventListener('click', handleClearAllCond1);\n  }\n\n  // Event delegation cho các nút Sao Chép và Xóa từng hàng trong bảng ĐK 1\n  if (elements.cond1TableBody) {\n    elements.cond1TableBody.addEventListener('click', (e) => {\n      const btnCopy = e.target.closest('.btn-cell-copy');\n      const btnDelete = e.target.closest('.btn-cell-delete');\n\n      if (btnCopy) {\n        const phone = btnCopy.dataset.phone;\n        const date = btnCopy.dataset.date || '';\n        if (phone) {\n          const textToCopy = date ? `${phone}\\t${date}` : phone;\n          navigator.clipboard.writeText(textToCopy);\n          showToast(`Đã sao chép: ${phone}${date ? ' - ' + date : ''}`, 'success');\n        }\n      } else if (btnDelete) {\n        const phone = btnDelete.dataset.phone;\n        if (phone) {\n          removeCondition1Item(phone);\n        }\n      }\n    });\n  }\n\n  // Copy ra Excel\n  elements.btnExportExcel.addEventListener('click', handleExportExcel);\n\n  // Xóa bảng & Xóa logs\n  elements.btnClearTable.addEventListener('click', () => {\n    appState.tableData = [];\n    renderTable();\n    showToast('Đã xóa dữ liệu bảng hiển thị.');\n  });\n\n  elements.btnClearLogs.addEventListener('click', () => {\n    elements.logsContainer.innerHTML = '';\n  });\n\n  // Lọc bảng\n  elements.inputTableSearch.addEventListener('input', (e) => {\n    appState.searchKeyword = e.target.value.toLowerCase().trim();\n    renderTable();\n  });\n\n  // Sắp xếp các cột bảng\n  document.querySelectorAll('.data-table th.sortable').forEach(th => {\n    th.addEventListener('click', () => {\n      const col = th.dataset.col;\n      if (appState.sortCol === col) {\n        appState.sortAsc = !appState.sortAsc;\n      } else {\n        appState.sortCol = col;\n        appState.sortAsc = true;\n      }\n      renderTable();\n    });\n  });\n}\n\n/**\n * Tải số lượng thông báo Telegram đã gửi\n */\nasync function loadTeleHistoryStats() {\n  try {\n    const res = await fetch('/api/telegram/history-stats');\n    const data = await res.json();\n    if (data.success && data.stats && elements.teleHistoryStatus) {\n      if (data.stats.totalAlerts > 0) {\n        elements.teleHistoryStatus.textContent = `📁 Đã lưu vết: ${data.stats.totalAlerts} thông báo (${data.stats.uniquePhones} số) - không gửi trùng khi chạy lại.`;\n      } else {\n        elements.teleHistoryStatus.textContent = '📁 Lịch sử thông báo trống (chưa có số nào được gửi).';\n      }\n    }\n  } catch (err) {}\n}\n\n/**\n * Xử lý xóa lịch sử thông báo Telegram\n */\nasync function handleResetTeleHistory() {\n  const ok = confirm('Bạn có chắc chắn muốn xóa lịch sử các số đã gửi thông báo Telegram?\\n\\nSau khi xóa, nếu bạn tra cứu lại các số đó thì bot sẽ gửi lại thông báo.');\n  if (!ok) return;\n\n  try {\n    if (elements.btnResetTeleHistory) elements.btnResetTeleHistory.disabled = true;\n    const res = await fetch('/api/telegram/reset-history', { method: 'POST' });\n    const data = await res.json();\n    if (data.success) {\n      showToast('Đã xóa sạch lịch sử thông báo Telegram!', 'success');\n      appendLog('info', 'Đã đặt lại lịch sử thông báo Telegram (file sent_notifications.json đã được xóa).');\n      loadTeleHistoryStats();\n    }\n  } catch (err) {\n    showToast(`Lỗi khi xóa: ${err.message}`, 'error');\n  } finally {\n    if (elements.btnResetTeleHistory) elements.btnResetTeleHistory.disabled = false;\n  }\n}\n\nfunction toggleTelegramBox(enable) {\n  if (enable) {\n    elements.telegramConfigBox.classList.add('visible');\n  } else {\n    elements.telegramConfigBox.classList.remove('visible');\n  }\n}\n\nfunction updatePhoneInputCount() {\n  const text = elements.inputPhoneList.value;\n  const lines = text.split(/[\\r\\n,;\\t]+/).filter(l => l.trim().length > 0);\n  elements.badgePhoneCount.textContent = `${lines.length} số`;\n}\n\n/**\n * Xử lý Start / Pause / Stop\n */\nasync function handleStart() {\n  const phoneList = elements.inputPhoneList.value.trim();\n  if (!phoneList) {\n    showToast('Vui lòng nhập danh sách số điện thoại cần tra cứu!', 'error');\n    elements.inputPhoneList.focus();\n    return;\n  }\n\n  const options = getFormSettings();\n\n  try {\n    elements.btnStart.disabled = true;\n    const res = await fetch('/api/start', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ phoneList, options })\n    });\n    const data = await res.json();\n    if (!data.success) {\n      showToast(data.error || 'Không thể bắt đầu tra cứu', 'error');\n      elements.btnStart.disabled = false;\n    }\n  } catch (err) {\n    showToast(`Lỗi gửi lệnh: ${err.message}`, 'error');\n    elements.btnStart.disabled = false;\n  }\n}\n\nasync function handlePause() {\n  try {\n    if (appState.status === 'running') {\n      await fetch('/api/pause', { method: 'POST' });\n    } else if (appState.status === 'paused') {\n      await fetch('/api/resume', { method: 'POST' });\n    }\n  } catch (err) {\n    showToast(`Lỗi: ${err.message}`, 'error');\n  }\n}\n\nasync function handleStop() {\n  try {\n    await fetch('/api/stop', { method: 'POST' });\n  } catch (err) {\n    showToast(`Lỗi: ${err.message}`, 'error');\n  }\n}\n\nasync function handleTestTelegram() {\n  const botToken = elements.inputTeleToken.value.trim();\n  const chatId = elements.inputTeleChatId.value.trim();\n\n  if (!botToken || !chatId) {\n    showToast('Vui lòng nhập đủ Telegram Bot Token và Chat ID', 'error');\n    return;\n  }\n\n  elements.btnTestTele.disabled = true;\n  elements.btnTestTele.textContent = '⏳ Đang gửi tin thử...';\n\n  try {\n    const res = await fetch('/api/test-telegram', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ botToken, chatId })\n    });\n    const data = await res.json();\n    if (data.success) {\n      showToast(' Đã gửi tin nhắn thử nghiệm thành công!', 'success');\n      appendLog('success', 'Gửi tin nhắn thử nghiệm Telegram thành công.');\n    } else {\n      showToast(` Gửi thất bại: ${data.error}`, 'error');\n      appendLog('error', `Lỗi Telegram: ${data.error}`);\n    }\n  } catch (err) {\n    showToast(`Lỗi kết nối: ${err.message}`, 'error');\n  } finally {\n    elements.btnTestTele.disabled = false;\n    elements.btnTestTele.textContent = '🔔 Kiểm tra gửi thử Telegram';\n  }\n}\n\n/**\n * Cập nhật trạng thái Runtime\n */\nfunction updateRuntimeStatus(status) {\n  appState.status = status;\n  const ind = elements.connectionBadge.querySelector('.status-indicator');\n\n  if (status === 'running') {\n    elements.connectionText.textContent = 'Đang tra cứu...';\n    ind.className = 'status-indicator running';\n    elements.btnStart.disabled = true;\n    elements.btnPause.disabled = false;\n    elements.btnPause.textContent = '⏸ Tạm Dừng';\n    elements.btnStop.disabled = false;\n  } else if (status === 'paused') {\n    elements.connectionText.textContent = 'Tạm dừng';\n    ind.className = 'status-indicator paused';\n    elements.btnStart.disabled = true;\n    elements.btnPause.disabled = false;\n    elements.btnPause.textContent = '▶ Tiếp Tục';\n    elements.btnStop.disabled = false;\n  } else if (status === 'stopped' || status === 'completed') {\n    elements.connectionText.textContent = status === 'completed' ? 'Hoàn thành' : 'Đã dừng';\n    ind.className = 'status-indicator ready';\n    elements.btnStart.disabled = false;\n    elements.btnPause.disabled = true;\n    elements.btnPause.textContent = '⏸ Tạm Dừng';\n    elements.btnStop.disabled = true;\n  } else {\n    elements.connectionText.textContent = 'Sẵn sàng';\n    ind.className = 'status-indicator ready';\n    elements.btnStart.disabled = false;\n    elements.btnPause.disabled = true;\n    elements.btnStop.disabled = true;\n  }\n}\n\nfunction updateStats(stats) {\n  if (stats.total !== undefined) elements.valTotal.textContent = stats.total;\n  if (stats.processed !== undefined) elements.valProcessed.textContent = stats.processed;\n  if (stats.condition1Count !== undefined) elements.valCond1.textContent = stats.condition1Count;\n  if (stats.condition2Count !== undefined) elements.valCond2.textContent = stats.condition2Count;\n  if (stats.cycle !== undefined) elements.cycleBadge.textContent = `Vòng: ${stats.cycle}`;\n}\n\n/**\n * Quản lý và hiển thị Bảng Ô Riêng ĐK 1 (Hàng dọc, sắp xếp, xóa từng số, xóa tất cả)\n */\nfunction addCondition1Item(phone, updatedDate) {\n  const existing = appState.condition1Items.find(x => x.phone === phone);\n  if (!existing) {\n    appState.condition1Items.push({\n      phone,\n      updatedDate: updatedDate || new Date().toLocaleString('vi-VN')\n    });\n    renderCondition1Table();\n  }\n}\n\nfunction removeCondition1Item(phone) {\n  appState.condition1Items = appState.condition1Items.filter(x => x.phone !== phone);\n  renderCondition1Table();\n  showToast(`Đã xóa số ${phone} khỏi ô riêng`, 'info');\n}\n\nfunction handleClearAllCond1() {\n  if (appState.condition1Items.length === 0) {\n    showToast('Ô ĐK 1 đang trống', 'info');\n    return;\n  }\n  const ok = confirm(`Bạn có chắc muốn xóa toàn bộ ${appState.condition1Items.length} số khỏi ô riêng này?`);\n  if (!ok) return;\n\n  appState.condition1Items = [];\n  renderCondition1Table();\n  showToast('Đã xóa tất cả các số khỏi ô ĐK 1', 'info');\n}\n\nfunction getSortedCondition1Items() {\n  let items = [...appState.condition1Items];\n  const sort = appState.sortCond1Col;\n\n  if (sort === 'phone-asc') {\n    items.sort((a, b) => a.phone.localeCompare(b.phone, 'vi', { numeric: true }));\n  } else if (sort === 'phone-desc') {\n    items.sort((a, b) => b.phone.localeCompare(a.phone, 'vi', { numeric: true }));\n  } else if (sort === 'date-desc') {\n    items.sort((a, b) => parseDateForSort(b.updatedDate) - parseDateForSort(a.updatedDate));\n  } else if (sort === 'date-asc') {\n    items.sort((a, b) => parseDateForSort(a.updatedDate) - parseDateForSort(b.updatedDate));\n  }\n  return items;\n}\n\nfunction handleCopyAllCond1() {\n  const items = getSortedCondition1Items();\n  if (items.length === 0) {\n    showToast('Chưa có số nào trong ô ĐK 1 để sao chép', 'error');\n    return;\n  }\n  // Sao chép cả số điện thoại và ngày thay đổi theo đúng thứ tự hiển thị (tab-delimited để dán vào Excel thành 2 cột)\n  const allLines = items.map(x => `${x.phone}\\t${x.updatedDate || ''}`).join('\\n');\n  navigator.clipboard.writeText(allLines);\n  showToast(`📋 Đã sao chép ${items.length} số ĐK 1 (kèm ngày giờ, đúng thứ tự)!`, 'success');\n}\n\nfunction parseDateForSort(dateStr) {\n  if (!dateStr) return 0;\n  // Hỗ trợ dạng: \"DD/MM/YYYY HH:mm:ss\" hoặc \"YYYY-MM-DD\"\n  const parts = dateStr.match(/(\\d{1,2})\\/(\\d{1,2})\\/(\\d{4})(?:\\s+(\\d{1,2}):(\\d{1,2}):(\\d{1,2}))?/);\n  if (parts) {\n    const d = parseInt(parts[1], 10);\n    const m = parseInt(parts[2], 10) - 1;\n    const y = parseInt(parts[3], 10);\n    const hh = parseInt(parts[4] || 0, 10);\n    const mm = parseInt(parts[5] || 0, 10);\n    const ss = parseInt(parts[6] || 0, 10);\n    return new Date(y, m, d, hh, mm, ss).getTime();\n  }\n  const t = Date.parse(dateStr);\n  return isNaN(t) ? 0 : t;\n}\n\nfunction setCond1Sort(sortVal) {\n  appState.sortCond1Col = sortVal;\n  renderCondition1Table();\n}\n\nfunction toggleCond1HeaderSort(col) {\n  if (col === 'phone') {\n    if (appState.sortCond1Col === 'phone-asc') {\n      setCond1Sort('phone-desc');\n      if (elements.selectSortCond1) elements.selectSortCond1.value = 'phone-desc';\n    } else {\n      setCond1Sort('phone-asc');\n      if (elements.selectSortCond1) elements.selectSortCond1.value = 'phone-asc';\n    }\n  } else if (col === 'date') {\n    if (appState.sortCond1Col === 'date-desc') {\n      setCond1Sort('date-asc');\n      if (elements.selectSortCond1) elements.selectSortCond1.value = 'date-asc';\n    } else {\n      setCond1Sort('date-desc');\n      if (elements.selectSortCond1) elements.selectSortCond1.value = 'date-desc';\n    }\n  }\n}\n\nfunction renderCondition1Table() {\n  if (!elements.cond1TableBody) return;\n\n  const count = appState.condition1Items.length;\n  if (elements.badgeCond1Count) {\n    elements.badgeCond1Count.textContent = `${count} số`;\n  }\n\n  // Cập nhật icon mũi tên ở tiêu đề cột ĐK 1\n  if (elements.thCond1Phone) {\n    const icon = elements.thCond1Phone.querySelector('.sort-icon');\n    if (appState.sortCond1Col === 'phone-asc') {\n      if (icon) icon.textContent = '▲';\n      elements.thCond1Phone.classList.add('sorted');\n    } else if (appState.sortCond1Col === 'phone-desc') {\n      if (icon) icon.textContent = '▼';\n      elements.thCond1Phone.classList.add('sorted');\n    } else {\n      if (icon) icon.textContent = '⇅';\n      elements.thCond1Phone.classList.remove('sorted');\n    }\n  }\n  if (elements.thCond1Date) {\n    const icon = elements.thCond1Date.querySelector('.sort-icon');\n    if (appState.sortCond1Col === 'date-asc') {\n      if (icon) icon.textContent = '▲';\n      elements.thCond1Date.classList.add('sorted');\n    } else if (appState.sortCond1Col === 'date-desc') {\n      if (icon) icon.textContent = '▼';\n      elements.thCond1Date.classList.add('sorted');\n    } else {\n      if (icon) icon.textContent = '⇅';\n      elements.thCond1Date.classList.remove('sorted');\n    }\n  }\n\n  if (count === 0) {\n    elements.cond1TableBody.innerHTML = `\n      <tr class=\"empty-row\" id=\"emptyCond1Row\">\n        <td colspan=\"4\" style=\"text-align: center; padding: 24px; color: var(--text-muted); font-style: italic;\">\n          Chưa có số nào thỏa mãn ĐK 1. Khi tìm thấy số sẵn sàng sử dụng tại Kho chung VNP, số sẽ xuất hiện tại đây theo từng hàng dọc.\n        </td>\n      </tr>\n    `;\n    return;\n  }\n\n  // Lấy danh sách đã sắp xếp đúng theo thứ tự hiển thị\n  const items = getSortedCondition1Items();\n\n  // Render HTML\n  const rowsHtml = items.map((item, index) => {\n    return `\n      <tr>\n        <td class=\"col-stt\">${index + 1}</td>\n        <td class=\"col-phone\">${item.phone}</td>\n        <td class=\"col-date\">${item.updatedDate || '--:--:--'}</td>\n        <td class=\"col-action\">\n          <div class=\"cond1-action-buttons\">\n            <button type=\"button\" class=\"btn-cell-copy\" data-phone=\"${item.phone}\" data-date=\"${item.updatedDate || ''}\" title=\"Sao chép số ${item.phone} và ngày thay đổi\">\n              📋 Sao chép\n            </button>\n            <button type=\"button\" class=\"btn-cell-delete\" data-phone=\"${item.phone}\" title=\"Xóa số ${item.phone} khỏi ô riêng\">\n              🗑️ Xóa\n            </button>\n          </div>\n        </td>\n      </tr>\n    `;\n  }).join('');\n\n  elements.cond1TableBody.innerHTML = rowsHtml;\n}\n\n/**\n * Thêm hàng vào bảng kết quả\n */\nfunction addTableRow(item) {\n  // Cập nhật hoặc thêm mới vào mảng dữ liệu\n  const existingIdx = appState.tableData.findIndex(row => row.phone === item.phone);\n  if (existingIdx >= 0) {\n    appState.tableData[existingIdx] = item;\n  } else {\n    appState.tableData.unshift(item);\n  }\n\n  renderTable();\n}\n\n/**\n * Lấy dữ liệu bảng chính hiện tại theo đúng bộ lọc và thứ tự sắp xếp hiển thị\n */\nfunction getCurrentDisplayData() {\n  let displayData = [...appState.tableData];\n\n  // Lọc theo từ khóa\n  if (appState.searchKeyword) {\n    const kw = appState.searchKeyword.toLowerCase().trim();\n    displayData = displayData.filter(r => \n      (r.phone && r.phone.toLowerCase().includes(kw)) ||\n      (r.productStatus && r.productStatus.toLowerCase().includes(kw)) ||\n      (r.warehouse && r.warehouse.toLowerCase().includes(kw)) ||\n      (r.updatedDate && r.updatedDate.toLowerCase().includes(kw))\n    );\n  }\n\n  // Sắp xếp\n  if (appState.sortCol) {\n    const col = appState.sortCol;\n    const factor = appState.sortAsc ? 1 : -1;\n    displayData.sort((a, b) => {\n      if (col === 'date') {\n        const tA = parseDateForSort(a.updatedDate);\n        const tB = parseDateForSort(b.updatedDate);\n        return (tA - tB) * factor;\n      }\n      let valA = '';\n      let valB = '';\n      if (col === 'phone') {\n        valA = a.phone || '';\n        valB = b.phone || '';\n      } else if (col === 'status') {\n        valA = a.productStatus || '';\n        valB = b.productStatus || '';\n      } else if (col === 'warehouse') {\n        valA = a.warehouse || '';\n        valB = b.warehouse || '';\n      } else {\n        valA = a[col] || '';\n        valB = b[col] || '';\n      }\n      return valA.localeCompare(valB, 'vi', { numeric: true, sensitivity: 'base' }) * factor;\n    });\n  }\n\n  return displayData;\n}\n\n/**\n * Vẽ lại bảng theo bộ lọc và sắp xếp\n */\nfunction renderTable() {\n  const displayData = getCurrentDisplayData();\n\n  // Cập nhật biểu tượng mũi tên sắp xếp ở tiêu đề cột bảng chính\n  document.querySelectorAll('.data-table th.sortable').forEach(th => {\n    const col = th.dataset.col;\n    const icon = th.querySelector('.sort-icon');\n    if (icon) {\n      if (appState.sortCol === col) {\n        icon.textContent = appState.sortAsc ? '▲' : '▼';\n        th.classList.add('sorted');\n      } else {\n        icon.textContent = '⇅';\n        th.classList.remove('sorted');\n      }\n    }\n  });\n\n  // Render HTML\n  if (displayData.length === 0) {\n    elements.tableBody.innerHTML = `\n      <tr class=\"empty-row\">\n        <td colspan=\"5\">Không có dữ liệu phù hợp.</td>\n      </tr>\n    `;\n    return;\n  }\n\n  let html = '';\n  for (const row of displayData) {\n    let rowClass = '';\n    if (row.isCondition1) rowClass = 'row-cond1';\n    else if (row.isCondition2) rowClass = 'row-cond2';\n\n    let statusTagClass = 'neutral';\n    if (row.productStatus === 'Sẵn sàng sử dụng') statusTagClass = 'ready';\n    else if (row.productStatus === 'Đã book số') statusTagClass = 'booked';\n\n    html += `\n      <tr class=\"${rowClass}\">\n        <td class=\"cell-phone\">${row.phone}</td>\n        <td>\n          <span class=\"status-tag ${statusTagClass}\">${row.productStatus}</span>\n        </td>\n        <td>\n          <span class=\"warehouse-tag\">${row.warehouse}</span>\n        </td>\n        <td class=\"cell-date\">${row.updatedDate}</td>\n        <td>\n          <button type=\"button\" class=\"btn-row-copy\" title=\"Sao chép dòng này\" onclick=\"copySingleRow('${row.phone}', '${row.productStatus}', '${row.warehouse}', '${row.updatedDate}')\">\n            📋 Copy\n          </button>\n        </td>\n      </tr>\n    `;\n  }\n\n  elements.tableBody.innerHTML = html;\n}\n\nwindow.copySingleRow = function(phone, status, warehouse, date) {\n  const text = `${phone}\\t${status}\\t${warehouse}\\t${date}`;\n  navigator.clipboard.writeText(text);\n  showToast(`Đã sao chép dòng số ${phone} (chuẩn dán Excel)!`, 'success');\n};\n\n/**\n * Xuất dữ liệu bảng để dán trực tiếp vào Excel (Tab-Separated Values - TSV)\n * Đảm bảo xuất đúng 100% theo thứ tự người dùng đã lọc và sắp xếp trên màn hình!\n */\nfunction handleExportExcel() {\n  const displayData = getCurrentDisplayData();\n  if (displayData.length === 0) {\n    showToast('Bảng chưa có dữ liệu để xuất!', 'error');\n    return;\n  }\n\n  // Header\n  const headers = ['Số thuê bao', 'Trạng thái sản phẩm', 'Hàng đang tại kho', 'Ngày thay đổi'];\n  const rows = [headers.join('\\t')];\n\n  for (const r of displayData) {\n    rows.push([r.phone, r.productStatus, r.warehouse, r.updatedDate].join('\\t'));\n  }\n\n  const tsvText = rows.join('\\n');\n  navigator.clipboard.writeText(tsvText);\n  showToast(`📋 Đã sao chép ${displayData.length} dòng dữ liệu theo đúng thứ tự hiển thị! Bạn có thể dán (Ctrl+V) thẳng vào Excel.`, 'success');\n}\n\n/**\n * Ghi nhật ký (Log)\n */\nfunction appendLog(type, message) {\n  const entry = document.createElement('div');\n  entry.className = `log-entry ${type}`;\n\n  const now = new Date();\n  const pad = n => String(n).padStart(2, '0');\n  const timeStr = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;\n\n  entry.innerHTML = `<span class=\"log-time\">${timeStr}</span><span class=\"log-text\">${escapeHtml(message)}</span>`;\n  elements.logsContainer.appendChild(entry);\n  elements.logsContainer.scrollTop = elements.logsContainer.scrollHeight;\n}\n\nfunction escapeHtml(str) {\n  return String(str).replace(/[&<>\"']/g, m => ({\n    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'\n  })[m]);\n}\n\n/**\n * Toast thông báo\n */\nfunction showToast(msg, type = 'info') {\n  const toast = document.createElement('div');\n  toast.className = `toast ${type}`;\n  toast.textContent = msg;\n  elements.toastContainer.appendChild(toast);\n\n  setTimeout(() => {\n    toast.style.opacity = '0';\n    toast.style.transform = 'translateY(10px)';\n    setTimeout(() => toast.remove(), 300);\n  }, 3500);\n}\n"};